// SPDX-License-Identifier: BSD-3-Clause
//
//! The build half of the runtime route: four modules and two generated files.
//!
//! An SDK that ships the runtime route calls `createModule` in place of
//! `translate_c.createModule()` and imports what comes back as its `c` module.
//! Nothing here links a native archive. That is the point: in this
//! configuration every `re2br_*` symbol arrives through the platform loader at
//! run time, and linking `libre2bridge` as well would make the linker demand
//! them before `load` ever runs.
//!
//!   rt        runtime/loader.zig, the reusable core, supplied by the driver.
//!             Pure Zig; imported by the facade in both configurations, because
//!             `LoadSource` and `LoadError` are this SDK's public types and must
//!             be the same types whichever configuration is built.
//!   library   runtime/library.zig, this SDK's descriptor: the namespaced
//!             synchronization binding and the load-time checks.
//!   dispatch  generated by runtime/generate.zig from the real translation
//!             output: the table, the wrappers, `load`, and the re-exported
//!             translated namespace. It imports `rt`, `library` and the
//!             patched translation as `c_native`.
//!   native    the generator's second file: the same translation with the
//!             `__root` prologue Aro writes replaced by an import of the
//!             dispatch as `c_routed`, so a declaration nested inside a
//!             translated type names the routed wrapper rather than the raw
//!             extern. It imports the dispatch and nothing else.
//!   sync.c    compiled into the dispatch with
//!             `-DRT_SYNC_PREFIX=re2_rt`, so its symbols cannot collide with
//!             another SDK's.
//!
//! ## Why no upstream include root goes on the translation line
//!
//! This is the one place where re2's graph is not a copy of s2geometry's, and
//! the reason is a fact about this SDK's header rather than a preference.
//! `zig/bridge.h:81-82` includes `<stddef.h>` and `<stdint.h>` and nothing
//! else, and it names no upstream type: `RE2::Options` reaches the caller as
//! `Re2BridgeOptions` (`zig/bridge.h:157-186`) and `absl::string_view` never
//! appears anywhere in the file.  So the translator resolves the whole header
//! out of the C library the compiler supplies, and `vendor/re2` and
//! `vendor/abseil-cpp` on the translation line would be `-I` roots that resolve
//! nothing.  They are deliberately absent here, and `build.zig`'s `addGraph`
//! keeps them off its own `addTranslateC` for the same reason -- the comment
//! there says which three include directories exist and which module needs
//! which.
//!
//! The compiled side is the opposite and is not in tension with this: RE2's own
//! public header is C++17 and reaches Abseil by name
//! (`vendor/re2/re2/re2.h:221-222`), so `zig/bridge.cc` needs all three roots
//! (`zig/`, `vendor/re2/`, `vendor/abseil-cpp/`) and a consumer that breaks
//! against a changed upstream header breaks there.  That is the direction a
//! break should be caught in, because the translation is a description of *this
//! bridge header* and nothing else.
//!
//! ## What the provider is, and why it is not `libre2`
//!
//! The whole routed surface is this fork's own C bridge: nine entry points,
//! every one of them defined in `zig/bridge.cc`.  An upstream `libre2` at any
//! version exports **none** of them, because upstream has no such header
//! (`zig/bridge.h:12-19` says why the bridge exists at all: `addTranslateC`
//! translates C, and RE2 is C++17 with classes and `absl::string_view`).  So a
//! loaded provider for this SDK is a shared `libre2bridge.so.0` -- or
//! `.dylib`, or `re2bridge.dll` -- whose own `DT_NEEDED` closure carries
//! `libre2.so.11` and, through it, `libabsl.so.2505`.  Naming an installed
//! `libre2.so` instead is refused with `MissingSymbol` on the first `re2br_*`
//! lookup, which is the honest answer: it is not a provider for this header,
//! and `runtime/library.zig` writes out the whole boundary.
//!
//! ## What this module deliberately does not do
//!
//! It links nothing native. It does not add RE2's or Abseil's include roots to
//! a module, does not name `libre2bridge`, and does not call
//! `linkSystemLibrary`. If a runtime-loading build ever fails to link because
//! `re2br_match` is undefined, something other than this file added that
//! library to the graph -- this one has no path by which it could.
//!
//! It also does not decide anything about targets. `wasm32-wasi` builds this
//! dispatch and the loader core exactly like any other target; the loader core
//! answers every request there with `UnsupportedTarget`, because WASI has no
//! `dlopen` (`runtime/loader.zig`, `supported_target`). That refusal is the
//! loader's, it happens at run time, and it is not a reason to exclude WASI
//! from the graph: WASI stays a fully supported target for the linked
//! configuration, which is the default.  The one WASI fact this SDK's
//! `runtime/sync.c` owns is in the other direction and agrees:
//! `runtime/sync.c:36-49` compiles a WASI backend whose lock/unlock/wait/broadcast
//! are no-ops and whose `thread_self` is the constant 1, which is the right
//! answer for the single-threaded model that route runs under.

const std = @import("std");

/// The prefix `runtime/sync.c` is compiled with.
///
/// `runtime/library.zig` declares the same prefix in the symbol names it binds.
/// The two must agree, and a build where they do not fails to link, which is
/// the whole error report: there is no runtime path that could hide it.
///
/// A build that needs a second, independent instance of this SDK in one binary
/// should change this value *and* the prefix in `runtime/library.zig`, and then
/// give the second instance its own copy of both files. Nothing else in the
/// package assumes one instance.
const sync_prefix = "re2_rt";

/// `extern` declarations that the C library provides and that must therefore
/// stay direct.
///
/// ## What this list holds
///
/// `zig/bridge.h:81-82` includes exactly two headers before its `extern "C"`
/// block: `<stddef.h>` and `<stdint.h>`.  Every name below was read out of the
/// pinned Zig 0.16.0 libc headers this graph's translator will use, target by
/// target, and every line below names the file and line it was read from.
///
/// Four of the six `check` targets contribute nothing at all:
///
///   * `x86_64-linux-gnu`, `aarch64-linux-gnu` and `riscv64-linux-gnu`
///     resolve `<stddef.h>` to the compiler's own builtin
///     `lib/include/stddef.h`, which includes only
///     `__stddef_ptrdiff_t.h`, `__stddef_size_t.h`, `__stddef_wchar_t.h`,
///     `__stddef_null.h`, `__stddef_offsetof.h` -- types and `NULL`, no
///     declaration.  There is no `generic-glibc/stddef.h` to reach instead.
///     `<stdint.h>` is `libc/include/generic-glibc/stdint.h`, whose includes
///     are `bits/libc-header-start.h` (`:26`), `bits/wordsize.h` (`:29`),
///     `bits/stdint-intn.h` (`:38`), `bits/stdint-uintn.h` (`:41`) and
///     `bits/stdint-least.h` (`:45`); the first reaches `features.h`, which
///     reaches `features-time64.h`, `stdc-predef.h`, `sys/cdefs.h` and
///     `gnu/stubs.h`, and `sys/cdefs.h:730-731` reaches `bits/wordsize.h` and
///     `bits/long-double.h`.  `gnu/stubs*.h` are `__stub_FUNCTION` macros,
///     `sgidefs.h` and `bits/long-double.h` are typedefs and attributes, and
///     the only line in the whole closure that matches a function declaration
///     is a `_Static_assert` at `generic-glibc/sys/cdefs.h:763`.  No name is
///     claimed for these three.
///   * `aarch64-macos-none` resolves both headers under
///     `libc/include/any-darwin-any/`.  `stddef.h:64-83` reaches `_types.h`,
///     `sys/_types.h` and the `sys/_types/_*.h` typedef headers; `stdint.h:18-59`
///     reaches `sys/_types/_int8_t.h` through `_uint64_t.h`,
///     `sys/_types/_intptr_t.h`, `_uintptr_t.h`, `_types/_intmax_t.h` and
///     `_types/_uintmax_t.h`.  `_types.h:30-33` adds `_bounds.h` and
///     `machine/_types.h`, and `sys/_types.h:32-33,42,94` adds `sys/cdefs.h`,
///     `machine/_types.h`, `sys/_types/_null.h` and
///     `sys/_pthread/_pthread_types.h`.  Every one of those files declares
///     types and macros; the two lines in `any-darwin-any/sys/cdefs.h` that
///     match a declaration pattern (`:532`, `:535`) are inside a comment.  No
///     name is claimed for Darwin.
///   * `wasm32-wasi` has no `stddef.h` or `stdint.h` of its own under
///     `libc/include/wasm-wasi-musl/`; both resolve into the musl tree, so
///     this row is the musl row and nothing is claimed for it.
///
/// Two rows do contribute, and both are the same musl-family shape as
/// s2geometry's: `generic-musl/stddef.h:19` reaches `bits/alltypes.h` and
/// `generic-musl/stdint.h:20,95` reaches `bits/alltypes.h` and
/// `bits/stdint.h`, all of which are `__NEED_*` typedefs and limit macros.
/// `libc/include/wasm-wasi-musl/bits/` carries the same two files for the
/// same reason.  No name is claimed for musl or WASI.
///
/// The mingw-w64 target is the one that contributes, and every name below is
/// from `libc/include/any-windows-any/`.  `<stddef.h>` reaches
/// `crtdefs.h:10` and then `corecrt.h:10`, which is `_mingw.h`; `<stdint.h>`
/// reaches `crtdefs.h` at `:28` and `<stddef.h>` at `:32`, so both includes
/// arrive at the same headers.  The declarations they produce, and only those:
///
///   `_errno`                `any-windows-any/stddef.h:18`
///   `_set_errno`            `any-windows-any/stddef.h:20`
///   `_get_errno`            `any-windows-any/stddef.h:21`
///   `__threadid`            `any-windows-any/stddef.h:24`
///   `__threadhandle`        `any-windows-any/stddef.h:26`
///   `__mingw_get_crt_info`  `any-windows-any/_mingw.h:665`
///   `__prefetch`            `any-windows-any/_mingw.h:650`
///
/// `__prefetch` is guarded by `defined(__arm__) || defined(__aarch64__) ||
/// defined(__arm64ec__)` at `_mingw.h:649`, so `x86_64-windows-gnu` -- the
/// Windows target in `check` -- does not declare it.  It is here anyway,
/// because this list is one string for every target rather than one per target,
/// and `-Dtarget=aarch64-windows-gnu` is a target a caller may name.
///
/// Three declarations in the same headers are deliberately *not* listed.
/// `__debugbreak` (`_mingw.h:604`) and `__fastfail` (`_mingw.h:625`) are each
/// declared and then defined in the same header under `__MINGW_INTRIN_INLINE`,
/// which `_mingw.h:89-90` defines as
/// `extern __inline__ __attribute__((__always_inline__,__gnu_inline__))`; a
/// declaration with a body is a definition, not an import, so the generator
/// copies the definition instead of routing an address for it.  `__prefetch` is
/// in the same shape at `_mingw.h:650-651`, and is listed anyway because the
/// cost of listing it is zero and the cost of missing it is a load that fails
/// on the first lookup.
///
/// Three more targets were read and no name is claimed for any of them:
/// `generic-freebsd/stddef.h:35-37` and `stdint.h:32-36`,
/// `generic-netbsd/stddef.h:37-39,56` and `stdint.h:35-100`, and
/// `generic-openbsd/stddef.h:38-40` and `stdint.h:22-23`.  Those four pairs
/// declare nothing themselves, but each reaches an arch-specific
/// `machine/*.h` that this sweep did not classify, and claiming a name from a
/// header nobody read is exactly the failure this list exists to prevent.
/// None of the three is in `check`'s matrix.
///
/// The two consequences are both deliberate:
///
///   * The list below is those seven names, so nothing else is quietly kept
///     direct. Were a libc name listed here and a future bridge header also
///     declared something spelled that way, the bridge's own symbol would stop
///     being resolved at load time -- a silent hole.
///   * If `zig/bridge.h` ever reaches `<string.h>`, `<stdlib.h>` or
///     `<math.h>`, this is the line that has to grow, and it is a build-file
///     change with a name in it rather than a load that fails with
///     `MissingSymbol` on `memcpy`.
///
/// Punctuation is load-bearing in the string below, and the rule is stated
/// rather than assumed.  `runtime/generate.zig`'s `addNames` (`:203-215`)
/// splits the list on commas and trims `" \t\r\n"` off each part (`:208`,
/// `:213`), which is what makes a wrapped list mean what it looks like, and it
/// skips an empty part (`:214`) -- so a trailing comma costs nothing and every
/// line below carries one.  What would cost something is a *missing* comma:
/// two names would arrive as one, that name would match nothing, and both would
/// be routed to be resolved from the provider instead of staying direct.
const libc_noise =
    \\__prefetch,
    \\__threadhandle,
    \\__threadid,
    \\_errno,
    \\_get_errno,
    \\_mingw_get_crt_info,
    \\_set_errno,
;

/// `extern` declarations the provider may legitimately not export.
///
/// None, and that is a source fact rather than an omission.  `zig/bridge.h`
/// declares nine entry points and `zig/bridge.cc` defines nine with the same
/// names (`re2br_options_init`, `re2br_compile`, `re2br_regex_error`,
/// `re2br_regex_group_count`, `re2br_regex_destroy`, `re2br_match`,
/// `re2br_extract`, `re2br_quote_meta`, `re2br_check_rewrite`).  Comparing the
/// two sets of names leaves nothing on either side.  There is also no
/// configuration-dependent declaration and no exported data symbol: every
/// `RE2BRIDGE_*` name in the header is a `#define`
/// (`zig/bridge.h:114-117`, `:120-122`, `:134`), so each is a translated
/// constant rather than an object a provider would have to export, and the
/// header declares no `extern` variable at all.
const provider_optional = "";

/// `extern` declarations this build does not require from a provider.
///
/// None.  Every one of the nine bridge entry points is expected from a
/// provider, and a provider that does not export one of them is refused rather
/// than half used.  A name here would be routed into a nullable table field
/// instead: its absence would not fail the load, and its wrapper would stop the
/// program by name.  Only `libc_noise` above keeps a declaration direct.
const provider_excluded = "";

/// The loader core, for a *linked* build to import.
///
/// A linked build has no dispatch, so the facade needs the core module itself
/// for the two public types `LoadSource` and `LoadError`: they are this SDK's
/// types and they must be the same types a caller names in either
/// configuration.  It costs a linked build two declarations and no code, since
/// nothing else in that module is referenced until a configuration actually
/// instantiates the loader.
///
/// A runtime-loading build must *not* import this separately: `createModule`
/// makes the one core instance the dispatch uses, and the dispatch re-exports
/// the two types from it.  Two instances would be two sets of types, and a
/// consumer would be naming one while `load` expects the other.
pub fn createCoreModule(
    b: *std.Build,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
) *std.Build.Module {
    return b.createModule(.{
        .root_source_file = b.path("runtime/loader.zig"),
        .target = target,
        .optimize = optimize,
        // The Unix backend calls `dlopen`, which is libc. Nothing in this module
        // is compiled into a linked build, so this costs nothing there.
        .link_libc = true,
    });
}

/// The runtime-loaded `c` module for one target.
///
/// `translate` is the translation step for that same target and configuration;
/// its output is read by the generator, so the dispatch describes the header
/// this build actually selected rather than another one.  The bundled graph and
/// the `-fsys=re2` graph both pass their own step, and both translate the same
/// `zig/bridge.h`, so both produce the same nine routed names.
///
/// No include path is added here, and the module doc above says why: the
/// header this translates names no upstream type, so there is nothing for a
/// `-I` root to resolve.  `RE2_USE_ICU`, RE2's one optional dependency
/// (`vendor/re2/CMakeLists.txt:16`, defined only under the option at `:98-102`),
/// is not reached and not linked here either.
pub fn createModule(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
) *std.Build.Module {
    const core = createCoreModule(b, target, optimize);

    const library = b.createModule(.{
        .root_source_file = b.path("runtime/library.zig"),
        .target = target,
        .optimize = optimize,
    });
    library.addImport("rt", core);

    return createDispatchModule(b, translate, target, optimize, core, library);
}

/// What one generator run writes: the dispatch, and the translation it reads.
const GeneratedSources = struct {
    native: std.Build.LazyPath,
    dispatch: std.Build.LazyPath,
};

fn createDispatchModule(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
    core: *std.Build.Module,
    library: *std.Build.Module,
) *std.Build.Module {
    const sources = generateDispatch(b, translate, target);

    // The patched translation, under a name that says what it is. Every type and
    // constant in the dispatch is re-exported from here rather than restated, so
    // `c.Re2BridgeSpan` in a facade and `c_native.Re2BridgeSpan` in the dispatch
    // are one nominal type, and `c_routed` is what makes the members nested
    // inside those types the routed wrappers.
    const native = b.createModule(.{
        .root_source_file = sources.native,
        .target = target,
        .optimize = optimize,
        .link_libc = true,
    });

    const dispatch = b.createModule(.{
        .root_source_file = sources.dispatch,
        .target = target,
        .optimize = optimize,
        .link_libc = true,
    });
    dispatch.addImport("rt", core);
    dispatch.addImport("library", library);
    dispatch.addImport("c_native", native);
    native.addImport("c_routed", dispatch);
    dispatch.addCSourceFiles(.{
        .files = &.{"runtime/sync.c"},
        .flags = &.{b.fmt("-DRT_SYNC_PREFIX={s}", .{sync_prefix})},
        .language = .c,
    });
    return dispatch;
}

/// Runs the generator over the translation step's real output.
///
/// The generator is a host program built and run by this build, so the dispatch
/// is produced for the target being built from that target's own translation.
/// Nothing is cached across configurations: a different header configuration
/// produces a different translation step output, which produces a different
/// dispatch.
fn generateDispatch(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
) GeneratedSources {
    const generator = b.addExecutable(.{
        .name = b.fmt("re2-runtime-generate-{s}", .{
            target.result.zigTriple(b.allocator) catch @panic("unspellable target"),
        }),
        .root_module = b.createModule(.{
            .root_source_file = b.path("runtime/generate.zig"),
            .target = b.graph.host,
            .optimize = .Debug,
        }),
    });

    const run = b.addRunArtifact(generator);
    run.addArg("--library");
    run.addArg("re2");
    run.addArg("--translate");
    run.addFileArg(translate.getOutput());
    if (libc_noise.len != 0) {
        run.addArg("--noise");
        run.addArg(libc_noise);
    }
    if (provider_optional.len != 0) {
        run.addArg("--optional");
        run.addArg(provider_optional);
    }
    if (provider_excluded.len != 0) {
        run.addArg("--exclude");
        run.addArg(provider_excluded);
    }
    run.addArg("--native-output");
    const native_source = run.addOutputFileArg("native.zig");
    run.addArg("--output");
    const dispatch_source = run.addOutputFileArg("dispatch.zig");
    return .{ .native = native_source, .dispatch = dispatch_source };
}
